package br.com.brindespro.quote;
import br.com.brindespro.pricing.PricingService;import br.com.brindespro.order.OrderStatusHistory;import br.com.brindespro.order.OrderStatusHistoryRepository;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.util.*;
@Service public class QuoteService {private final QuoteRepository quotes;private final CustomerRepository customers;private final QuoteFileRepository files;private final PricingService pricing;private final OrderStatusHistoryRepository history;public QuoteService(QuoteRepository quotes,CustomerRepository customers,QuoteFileRepository files,PricingService pricing,OrderStatusHistoryRepository history){this.quotes=quotes;this.customers=customers;this.files=files;this.pricing=pricing;this.history=history;}
 public record CreateRequest(@NotBlank @Size(min=3,max=200) String customerName,@NotBlank @Size(min=2,max=200) String company,@NotBlank @Pattern(regexp="^\\+?[0-9()\\s-]{10,20}$") String phone,@Email @NotBlank String email,@Size(max=1000) String notes,@NotEmpty @Valid List<PricingService.Request> items){}
 public record ItemDto(Long productId,Long variantId,String productName,String color,String material,int quantity,String engraving,String printingPosition,String deadline,BigDecimal unitPrice,BigDecimal total,Long logoFileId){}
 public record QuoteDto(Long id,String number,String status,String orderStatus,String customerName,String company,String phone,String email,String notes,BigDecimal total,String createdAt,String updatedAt,String expectedDeliveryDate,String trackingCode,List<ItemDto> items){}
 public static QuoteDto dto(Quote q){return new QuoteDto(q.id,q.number,q.status,q.orderStatus,q.customer.name,q.customer.company,q.customer.phone,q.customer.email,q.notes,q.total,q.createdAt.toString(),q.updatedAt.toString(),q.expectedDeliveryDate==null?null:q.expectedDeliveryDate.toString(),q.trackingCode,q.items.stream().map(i->new ItemDto(i.productId,i.variantId,i.productName,i.color,i.material,i.quantity,i.engraving,i.printingPosition,i.deadline,i.unitPrice,i.lineTotal,i.logoFileId)).toList());}
 @Transactional public QuoteDto create(CreateRequest request){Customer customer=customers.save(new Customer(request.customerName(),request.company(),request.phone(),request.email()));Quote quote=new Quote(customer,request.notes()==null?"":request.notes());quote.status="Recebido";quote.orderStatus="RECEBIDO";Set<Long> usedFiles=new HashSet<>();for(var line:request.items()){var result=pricing.calculate(line);if(line.logoFileId()!=null){QuoteFile f=files.findById(line.logoFileId()).orElseThrow(()->new IllegalArgumentException("Arquivo de arte não encontrado."));if(line.logoToken()==null||!line.logoToken().equals(f.uploadToken)||f.quote!=null||!usedFiles.add(f.id))throw new IllegalArgumentException("Arquivo de arte inválido ou já utilizado.");}QuoteItem item=new QuoteItem(quote);item.productId=line.productId();item.variantId=line.variantId();item.kitId=line.kitId();item.productName=result.product().name;item.color=result.variant().color;item.material=result.variant().material;item.quantity=line.quantity();item.engraving=line.engraving();item.printingPosition=line.printingPosition();item.deadline=line.deadline();item.baseUnitPrice=result.baseUnitPrice();item.unitPrice=result.unitPrice();item.surcharge=result.surcharge();item.lineTotal=result.total();item.logoFileId=line.logoFileId();if(line.preview()!=null){item.previewX=line.preview().x();item.previewY=line.preview().y();item.previewScale=line.preview().scale();}quote.items.add(item);quote.total=quote.total.add(result.total());}quotes.saveAndFlush(quote);quote.number=String.format("BP-%06d",quote.id);for(var item:quote.items){if(item.logoFileId!=null){QuoteFile f=files.findById(item.logoFileId).orElseThrow();f.quote=quote;files.save(f);}}Quote saved=quotes.save(quote);history.save(new OrderStatusHistory(saved,"RECEBIDO","Pedido recebido. Nossa equipe analisará os detalhes.",true,"sistema"));return dto(saved);}
 public QuoteDto get(String number){return quotes.findByNumber(number).map(QuoteService::dto).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND,"Orçamento não encontrado."));}
}
